from collections import defaultdict

def main():
    # Read all input at once
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    iterator = iter(input_data)

    t = int(next(iterator))

    # First pass: collect all queries and find max_a
    queries = []
    max_a = 0
    for _ in range(t):
        n = int(next(iterator))
        piles = []
        for _ in range(n):
            a = int(next(iterator))
            piles.append(a)
            if a > max_a:
                max_a = a
        queries.append(piles)

    MAX = max_a + 1
